#!/bin/sh
# Bring up the four demo hosts and write an ssh config snippet so `@web`, `@api`,
# `@db`, `@worker` resolve from your real terminal. Idempotent.
set -eu

dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
keys="$dir/.keys"
inc="$HOME/.ssh/tmmx-demo.config"

mkdir -p "$keys"
[ -f "$keys/id_ed25519" ] || ssh-keygen -q -t ed25519 -N '' -f "$keys/id_ed25519" -C tmmx-demo
chmod 600 "$keys/id_ed25519"

TMMX_DEMO_KEYS_DIR="$keys" docker compose -f "$dir/compose.yaml" up -d --build

cat > "$inc" <<EOF
# Generated by tmmx demo/up.sh — removed by demo/down.sh.
Host web api db worker
  HostName 127.0.0.1
  User tmmx
  IdentityFile $keys/id_ed25519
  StrictHostKeyChecking no
  UserKnownHostsFile /dev/null
  LogLevel ERROR
Host web
  Port 2201
Host api
  Port 2202
Host db
  Port 2203
Host worker
  Port 2204
EOF
chmod 600 "$inc"

printf '\n✓ demo hosts up: web(2201) api(2202) db(2203) worker(2204)\n'
if ! grep -qs 'Include .*tmmx-demo.config' "$HOME/.ssh/config" 2>/dev/null; then
  printf '\nAdd this line to the TOP of ~/.ssh/config (once):\n\n    Include ~/.ssh/tmmx-demo.config\n\n'
fi
printf 'Then run tmmx, press your manager key, and type @ to see the hosts.\n'
